import * as THREE from 'three';

/** Length of one periodic stretch of canyon. The camera loops over exactly this length. */
export const L = 640;
export const K = (Math.PI * 2) / L;
const per = (n: number): number => n * K;

export const SUN = new THREE.Vector3(0.5, 0.19, -0.85).normalize();

function sstep(a: number, b: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

export const center = (z: number): number =>
  26 * Math.sin(per(2) * z + 0.5) + 5 * Math.sin(per(4) * z + 1.3);
export const halfWidth = (z: number): number =>
  15 + 3 * Math.sin(per(7) * z + 2) + 1.5 * Math.sin(per(13) * z + 0.3);
export const channel = (z: number): number => 4 * Math.sin(per(9) * z + 0.7);

function wallH(z: number, side: number): number {
  return (
    24 +
    9 * Math.sin(per(3) * z + side * 2.1) +
    5 * Math.sin(per(11) * z + side * 1.1) +
    3 * Math.sin(per(23) * z + side * 0.7)
  );
}
function wallD(z: number, side: number): number {
  return 9 + 3 * Math.sin(per(6) * z + side);
}
function noise(u: number, z: number): number {
  return (
    0.55 * Math.sin(0.31 * u + per(41) * z + 0.5 + 1.3 * Math.sin(per(17) * z + 0.2 * u)) +
    0.3 * Math.sin(0.83 * u - per(97) * z + 2.0) +
    0.15 * Math.sin(0.17 * u + per(29) * z)
  );
}
function noiseHi(u: number, z: number): number {
  return (
    0.5 * Math.sin(2.1 * u + per(113) * z + 1.0) +
    0.3 * Math.sin(3.3 * u - per(149) * z + 0.4) +
    0.2 * Math.sin(1.3 * u + per(71) * z)
  );
}

/** Smooth floor profile (no ripples), used for the camera height. */
export function floorBase(u: number, z: number): number {
  const d = u - channel(z);
  return 1.5 * Math.sin(per(2) * z + 1) - 0.7 * Math.exp(-(d * d) / 10);
}

/** Terrain height at offset u from the canyon centre line at world z. Periodic in z with period L. */
export function height(u: number, z: number): number {
  let y = floorBase(u, z) + 0.12 * noiseHi(u, z);
  const side = u < 0 ? 0 : 1;
  const a = Math.abs(u);
  const dd = a - halfWidth(z) + 2.5 * noise(u, z);
  if (dd > 0) {
    const hs = wallH(z, side);
    const d = wallD(z, side);
    const t = Math.min(1, dd / d);
    const sm = t * t * (3 - 2 * t);
    const hw = hs * sm;
    const s = hw / 5.5 + 0.35 * noise(u * 0.2 + 3, z);
    const fr = s - Math.floor(s);
    const st = (Math.floor(s) + sstep(0.6, 1.0, fr)) * 5.5;
    const f = sstep(0, 0.25, sm) * (1 - sstep(0.8, 1.0, sm));
    y += hw + (st - hw) * 0.55 * f + 0.9 * noiseHi(u, z) * sm * (1 - sstep(0.85, 1, sm) * 0.7);
  }
  return y;
}

/* ---- Height lookup table used only for sun shadow ray marching ---- */
export const NZ = 400;
export const DZ = L / NZ;
export const U0 = -112;
export const DU = 0.5;
export const NU = 449;

export function buildTable(): Float32Array {
  const t = new Float32Array(NZ * NU);
  for (let iz = 0; iz < NZ; iz++) {
    const z = iz * DZ;
    for (let iu = 0; iu < NU; iu++) t[iz * NU + iu] = height(U0 + iu * DU, z);
  }
  return t;
}

/** Raise a dome (boulder) in the table. x,z are world coordinates, y0 the ground height. */
export function addBump(tab: Float32Array, x: number, z: number, y0: number, r: number, h: number): void {
  const ci = Math.round(z / DZ);
  const n = Math.ceil(r / DZ) + 1;
  for (let k = -n; k <= n; k++) {
    const zz = (ci + k) * DZ;
    const iz = ((ci + k) % NZ + NZ) % NZ;
    const uu = x - center(zz);
    const dz = zz - z;
    const i0 = Math.max(0, Math.floor((uu - r - U0) / DU));
    const i1 = Math.min(NU - 1, Math.ceil((uu + r - U0) / DU));
    for (let iu = i0; iu <= i1; iu++) {
      const dx = U0 + iu * DU - uu;
      const d2 = dx * dx + dz * dz;
      if (d2 >= r * r) continue;
      const v = y0 + h * Math.sqrt(1 - d2 / (r * r));
      const idx = iz * NU + iu;
      if (v > tab[idx]) tab[idx] = v;
    }
  }
}

function sampleTab(tab: Float32Array, x: number, z: number): number {
  let fu = (x - center(z) - U0) / DU;
  if (fu < 0) fu = 0;
  else if (fu > NU - 1.001) fu = NU - 1.001;
  const fz = z / DZ;
  const k = Math.floor(fz);
  const tz = fz - k;
  const iz0 = ((k % NZ) + NZ) % NZ;
  const iz1 = (iz0 + 1) % NZ;
  const iu0 = Math.floor(fu);
  const tu = fu - iu0;
  const a = tab[iz0 * NU + iu0] * (1 - tu) + tab[iz0 * NU + iu0 + 1] * tu;
  const b = tab[iz1 * NU + iu0] * (1 - tu) + tab[iz1 * NU + iu0 + 1] * tu;
  return a * (1 - tz) + b * tz;
}

/** Soft sun visibility (0 shadow, 1 lit) by marching a ray towards the sun over the table. */
export function visibility(tab: Float32Array, x: number, y: number, z: number): number {
  let t = 0.5;
  let m = 1;
  const sx = SUN.x;
  const sy = SUN.y;
  const sz = SUN.z;
  while (t < 420) {
    const ry = y + sy * t + 0.1;
    if (ry > 47) break;
    const h = sampleTab(tab, x + sx * t, z + sz * t);
    const v = (ry - h) / (0.12 * t + 0.45);
    if (v < m) {
      m = v;
      if (m <= 0) return 0;
    }
    t += Math.max(0.6, t * 0.1);
  }
  return m >= 1 ? 1 : sstep(0, 1, m);
}

/** Build the canyon mesh covering z from +40 down to about -940. */
export function buildTerrain(tab: Float32Array): THREE.BufferGeometry {
  const us: number[] = [];
  for (let u = -110; u < -36; u += 3) us.push(u);
  for (let i = -72; i <= 72; i++) us.push(i * 0.5);
  for (let u = 39; u <= 110; u += 3) us.push(u);
  const kStart = 25;
  const kEnd = -588;
  const nr = kStart - kEnd + 1;
  const nc = us.length;
  const pos = new Float32Array(nr * nc * 3);
  const shade = new Float32Array(nr * nc);
  for (let r = 0; r < nr; r++) {
    const z = (kStart - r) * DZ;
    const c = center(z);
    for (let j = 0; j < nc; j++) {
      const u = us[j];
      const x = c + u;
      const y = height(u, z);
      const i = r * nc + j;
      pos[i * 3] = x;
      pos[i * 3 + 1] = y;
      pos[i * 3 + 2] = z;
      shade[i] = visibility(tab, x, y, z);
    }
  }
  const idx = new Uint32Array((nr - 1) * (nc - 1) * 6);
  let p = 0;
  for (let r = 0; r < nr - 1; r++) {
    for (let j = 0; j < nc - 1; j++) {
      const a = r * nc + j;
      const b = a + 1;
      const d = a + nc;
      const e = d + 1;
      idx[p++] = a;
      idx[p++] = b;
      idx[p++] = e;
      idx[p++] = a;
      idx[p++] = e;
      idx[p++] = d;
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('aShade', new THREE.BufferAttribute(shade, 1));
  geo.setAttribute('aCol', new THREE.BufferAttribute(new Float32Array(nr * nc * 3), 3));
  geo.setIndex(new THREE.BufferAttribute(idx, 1));
  geo.computeVertexNormals();
  // Make sure the surface faces up; flip the winding if not.
  const nrm = geo.getAttribute('normal');
  const mid = Math.floor(nr / 2) * nc + Math.floor(nc / 2);
  if (nrm.getY(mid) < 0) {
    for (let i = 0; i < idx.length; i += 3) {
      const t = idx[i + 1];
      idx[i + 1] = idx[i + 2];
      idx[i + 2] = t;
    }
    geo.computeVertexNormals();
  }
  geo.computeBoundingSphere();
  return geo;
}

import * as THREE from 'three';
import { L, SUN, addBump, center, channel, halfWidth, height, visibility, floorBase } from './terrain';
import { camU } from './camera';

void SUN;
void floorBase;

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

type RGB = [number, number, number];

class Acc {
  pos: number[] = [];
  nor: number[] = [];
  col: number[] = [];
  shade: number[] = [];

  /** Append geometry. If `fixedShade` is null the sun visibility is computed per vertex. */
  add(geo: THREE.BufferGeometry, color: RGB, tab: Float32Array, fixedShade: number | null, vary = 0, rng?: () => number): void {
    const g = geo.index ? geo.toNonIndexed() : geo;
    const p = g.getAttribute('position');
    const n = g.getAttribute('normal');
    for (let i = 0; i < p.count; i++) {
      const x = p.getX(i);
      const y = p.getY(i);
      const z = p.getZ(i);
      this.pos.push(x, y, z);
      this.nor.push(n.getX(i), n.getY(i), n.getZ(i));
      const v = vary && rng ? 1 + (rng() - 0.5) * vary : 1;
      this.col.push(color[0] * v, color[1] * v, color[2] * v);
      this.shade.push(fixedShade === null ? visibility(tab, x, y, z) : fixedShade);
    }
    if (g !== geo) g.dispose();
  }

  build(): THREE.BufferGeometry {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(this.pos), 3));
    geo.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(this.nor), 3));
    geo.setAttribute('aCol', new THREE.BufferAttribute(new Float32Array(this.col), 3));
    geo.setAttribute('aShade', new THREE.BufferAttribute(new Float32Array(this.shade), 1));
    geo.computeBoundingSphere();
    return geo;
  }
}

export interface Boulder {
  x: number;
  y: number;
  z: number;
  r: number;
  seed: number;
}

const ZMIN = -940;
const ZMAX = 40;

/** Replicate a base position (z in [0, L)) over the generated mesh range. */
function copies(zb: number): number[] {
  const out: number[] = [];
  for (let m = 0; m < 3; m++) {
    const z = zb - L * m;
    if (z <= ZMAX && z >= ZMIN) out.push(z);
  }
  return out;
}

export function placeBoulders(): Boulder[] {
  const rng = mulberry32(1234);
  const list: Boulder[] = [];
  for (let i = 0; i < 150; i++) {
    const zb = rng() * L;
    const r = 0.4 + Math.pow(rng(), 3) * 2.8;
    const w = halfWidth(zb);
    const side = rng() < 0.5 ? -1 : 1;
    const near = rng() < 0.45;
    const u = near ? side * (w - 3 + rng() * 6) : (rng() * 2 - 1) * (w - 1);
    if (Math.abs(u - camU(zb)) < r + 2.2) continue;
    const seed = Math.floor(rng() * 1e6);
    for (const z of copies(zb)) {
      const x = center(z) + u;
      list.push({ x, y: height(u, z), z, r, seed });
    }
  }
  return list;
}

export function applyBoulderBumps(tab: Float32Array, boulders: Boulder[]): void {
  for (const b of boulders) addBump(tab, b.x, b.z, b.y, b.r, b.r * 0.75);
}

const ROCK_COLS: RGB[] = [
  [0.55, 0.28, 0.18],
  [0.66, 0.42, 0.28],
  [0.5, 0.3, 0.28],
  [0.72, 0.55, 0.38],
];

export function buildRocks(boulders: Boulder[], tab: Float32Array): THREE.BufferGeometry {
  const acc = new Acc();
  for (const b of boulders) {
    const rng = mulberry32(b.seed);
    const geo = new THREE.IcosahedronGeometry(1, 2);
    const p = geo.getAttribute('position');
    const sy = 0.6 + rng() * 0.3;
    const sz = 1.0 + rng() * 0.2;
    const ph1 = rng() * 6.28;
    const ph2 = rng() * 6.28;
    const ph3 = rng() * 6.28;
    const rot = rng() * 6.28;
    const cr = Math.cos(rot);
    const sr = Math.sin(rot);
    for (let i = 0; i < p.count; i++) {
      const vx = p.getX(i);
      const vy = p.getY(i);
      const vz = p.getZ(i);
      const d = 1 + 0.22 * Math.sin(vx * 3.1 + ph1) * Math.sin(vy * 2.7 + ph2) + 0.12 * Math.sin(vz * 5 + ph3);
      let lx = vx * d * b.r;
      let ly = Math.max(vy * d * sy, -0.35 * sy) * b.r;
      let lz = vz * d * sz * b.r;
      const rx = lx * cr + lz * sr;
      const rz = -lx * sr + lz * cr;
      lx = rx;
      lz = rz;
      p.setXYZ(i, b.x + lx, b.y + 0.25 * sy * b.r + ly, b.z + lz);
    }
    geo.computeVertexNormals();
    const c = ROCK_COLS[Math.floor(rng() * ROCK_COLS.length)];
    acc.add(geo, c, tab, null, 0.25, rng);
    geo.dispose();
  }
  return acc.build();
}

export function buildShrubs(tab: Float32Array): THREE.BufferGeometry {
  const acc = new Acc();
  const up = new THREE.Vector3(0, 1, 0);
  const rng0 = mulberry32(777);

  const branch = (
    rng: () => number,
    M: THREE.Matrix4,
    col: RGB,
    shade: number,
    start: THREE.Vector3,
    dir: THREE.Vector3,
    len: number,
    r: number,
    depth: number,
  ): void => {
    const geo = new THREE.CylinderGeometry(r * 0.55, r, len, 4, 1, true);
    geo.translate(0, len / 2, 0);
    const q = new THREE.Quaternion().setFromUnitVectors(up, dir);
    geo.applyMatrix4(new THREE.Matrix4().compose(start, q, new THREE.Vector3(1, 1, 1)));
    geo.applyMatrix4(M);
    acc.add(geo, col, tab, shade, 0.3, rng);
    geo.dispose();
    if (depth > 0) {
      const kids = depth === 2 ? 3 : 2;
      for (let k = 0; k < kids; k++) {
        const t = 0.4 + rng() * 0.55;
        const ns = start.clone().addScaledVector(dir, len * t);
        const nd = dir
          .clone()
          .add(new THREE.Vector3(rng() - 0.5, rng() * 0.5 - 0.15, rng() - 0.5).multiplyScalar(1.6))
          .normalize();
        branch(rng, M, col, shade, ns, nd, len * 0.65, r * 0.6, depth - 1);
      }
    }
  };

  for (let i = 0; i < 130; i++) {
    const zb = rng0() * L;
    const ch = channel(zb);
    const w = halfWidth(zb);
    let u = ch + (rng0() - rng0()) * 12;
    if (Math.abs(u) > w + 1) u = (rng0() * 2 - 1) * w;
    if (Math.abs(u - camU(zb)) < 1.6) continue;
    const seed = Math.floor(rng0() * 1e6);
    const s = 0.8 + rng0() * 0.9;
    const rot = rng0() * 6.28;
    for (const z of copies(zb)) {
      const rng = mulberry32(seed);
      const x = center(z) + u;
      const y = height(u, z) - 0.05;
      const M = new THREE.Matrix4().compose(
        new THREE.Vector3(x, y, z),
        new THREE.Quaternion().setFromAxisAngle(up, rot),
        new THREE.Vector3(s, s, s),
      );
      const shade = visibility(tab, x, y + 0.5, z);
      const col: RGB = [0.3 + rng() * 0.08, 0.22 + rng() * 0.05, 0.16];
      const origin = new THREE.Vector3(0, 0, 0);
      for (let k = 0; k < 4; k++) {
        const ang = rng() * 6.28;
        const dir = new THREE.Vector3(Math.cos(ang) * 0.6, 0.8, Math.sin(ang) * 0.6).normalize();
        branch(rng, M, col, shade, origin, dir, 0.5 + rng() * 0.5, 0.06, 2);
      }
    }
  }
  return acc.build();
}

import * as THREE from 'three';
import { L, K, center, channel, floorBase } from './terrain';

const per = (n: number): number => n * K;

/** Drift of the camera relative to the centre line, as a function of distance travelled. */
function drift(s: number): number {
  return 2.5 * Math.sin(per(11) * s + 0.4) + 1.2 * Math.sin(per(19) * s + 2);
}

/** Camera lateral offset from the canyon centre line at world z (z = -s). */
export function camU(z: number): number {
  return channel(z) * 0.6 + drift(-z);
}

export function camPos(s: number, lift: number, out: THREE.Vector3): THREE.Vector3 {
  const z = -s;
  const u = camU(z);
  return out.set(center(z) + u, floorBase(u, z) + 2.4 + lift, z);
}

