export const GROUND_FRAG = /* glsl */ `
${COMMON}
varying vec3 vWorld;
varying vec3 vN;
varying float vShade;
varying vec3 vCol;

float h11(float n) { return fract(sin(n * 12.9898) * 43758.5453); }
vec3 lin(vec3 c) { return pow(c, vec3(2.2)); }
vec3 pal(float id) {
  float r = h11(id * 1.37 + 3.1);
  vec3 c;
  if (r < 0.2) c = vec3(0.50, 0.20, 0.12);
  else if (r < 0.4) c = vec3(0.74, 0.38, 0.18);
  else if (r < 0.6) c = vec3(0.82, 0.58, 0.36);
  else if (r < 0.8) c = vec3(0.60, 0.28, 0.26);
  else c = vec3(0.86, 0.70, 0.50);
  return lin(c);
}
float wn(vec3 w) {
  return 0.5 * sin(0.21 * w.x + 7.0 * uK * w.z + 1.0)
       + 0.3 * sin(0.13 * w.x - 11.0 * uK * w.z + 2.0)
       + 0.2 * sin(0.37 * w.x + 19.0 * uK * w.z);
}

void main() {
  vec3 N = normalize(vN);
  vec3 w = vWorld;
  vec3 albedo;
#ifdef TERRAIN
  float s = w.y * 0.16 + 0.9 * wn(w);
  float id = floor(s);
  float fr = fract(s);
  vec3 sc = pal(id) * mix(0.78, 1.0, smoothstep(0.0, 0.18, fr));
  float fine = h11(floor(w.y * 0.9 + 1.5 * wn(w.zyx * 1.7)));
  sc *= 0.82 + 0.3 * fine;
  float streak = 0.5 + 0.5 * sin(w.x * 1.9 + 53.0 * uK * w.z + 2.0 * wn(w));
  sc *= 1.0 - 0.2 * streak * (1.0 - N.y);
  float grain = 0.5 * (sin(w.x * 3.1 + 160.0 * uK * w.z) + sin(w.x * 1.7 - 90.0 * uK * w.z + 1.0));
  vec3 sand = lin(vec3(0.78, 0.60, 0.42));
  vec3 pale = lin(vec3(0.72, 0.64, 0.55));
  float patch = smoothstep(-0.2, 0.5, wn(vec3(w.x * 0.4, 0.0, w.z)));
  sand = mix(sand, pale, patch * 0.7) * (0.93 + 0.07 * grain);
  float sandMix = max(smoothstep(0.7, 0.92, N.y), 1.0 - smoothstep(2.0, 5.5, w.y));
  albedo = mix(sc, sand, sandMix);
#else
  float g = 0.5 + 0.5 * sin(w.x * 7.0 + w.y * 9.0 + 120.0 * uK * w.z);
  albedo = lin(vCol) * (0.85 + 0.25 * g);
#endif

  float ndl = max(dot(N, uSun), 0.0);
  vec3 sunCol = vec3(1.0, 0.50, 0.22) * 2.6;
  vec3 direct = sunCol * ndl * vShade;
  vec3 skyUp = vec3(0.13, 0.14, 0.34);
  vec3 bounce = vec3(0.30, 0.15, 0.09);
  vec3 amb = mix(bounce, skyUp, N.y * 0.5 + 0.5) * 1.15;
  vec3 col = albedo * (direct + amb);

  vec3 V = vWorld - cameraPosition;
  float dist = length(V);
  vec3 vd = V / dist;
  vec3 fogDir = normalize(vec3(vd.x, clamp(vd.y, 0.0, 0.4) * 0.6 + 0.015, vd.z));
  vec3 fogCol = skyBase(fogDir) * 0.92;
  float fa = 1.0 - exp(-dist * 0.0085);
  col = mix(col, fogCol, fa);
  gl_FragColor = vec4(tonemap(col), 1.0);
}
`;

import * as THREE from 'three';
import { L, K, SUN, buildTable, buildTerrain } from './terrain';
import { applyBoulderBumps, buildRocks, buildShrubs, placeBoulders } from './scatter';
import { camPos } from './camera';
import { GROUND_FRAG, GROUND_VERT, SKY_FRAG, SKY_VERT } from './shaders';

declare global {
  interface Window {
    __EVAL_READY__?: boolean;
  }
}

const canvas = document.getElementById('app') as HTMLCanvasElement;
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(1);
renderer.setSize(640, 360, false);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(62, 640 / 360, 0.1, 2000);

const uniforms = {
  uSun: { value: SUN.clone() },
  uK: { value: K },
  uTime: { value: 0 },
};

// Geometry
const terrTab = buildTable();
const boulders = placeBoulders();
const shadowTab = terrTab.slice();
applyBoulderBumps(shadowTab, boulders);

const terrainMat = new THREE.ShaderMaterial({
  uniforms,
  vertexShader: GROUND_VERT,
  fragmentShader: GROUND_FRAG,
  defines: { TERRAIN: '' },
});
const propMat = new THREE.ShaderMaterial({
  uniforms,
  vertexShader: GROUND_VERT,
  fragmentShader: GROUND_FRAG,
});

const terrain = new THREE.Mesh(buildTerrain(shadowTab), terrainMat);
terrain.frustumCulled = false;
scene.add(terrain);

const rocks = new THREE.Mesh(buildRocks(boulders, terrTab), propMat);
rocks.frustumCulled = false;
scene.add(rocks);

const shrubs = new THREE.Mesh(buildShrubs(terrTab), propMat);
shrubs.frustumCulled = false;
scene.add(shrubs);

const sky = new THREE.Mesh(
  new THREE.SphereGeometry(1000, 32, 16),
  new THREE.ShaderMaterial({
    uniforms,
    vertexShader: SKY_VERT,
    fragmentShader: SKY_FRAG,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: false,
  }),
);
sky.frustumCulled = false;
sky.renderOrder = -1;
scene.add(sky);

const SPEED = 5.5;
const pos = new THREE.Vector3();
const target = new THREE.Vector3();
let first = true;

function frame(now: number): void {
  const t = now / 1000;
  const s = (t * SPEED) % L;
  uniforms.uTime.value = t;
  camPos(s, 0.04 * Math.sin(t * 1.7), pos);
  camera.position.copy(pos);
  camPos(s + 24, 2.3, target);
  camera.lookAt(target);
  camera.rotateZ(0.02 * Math.sin(t * 0.35));
  sky.position.copy(pos);
  renderer.render(scene, camera);
  if (first) {
    first = false;
    window.__EVAL_READY__ = true;
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

